package io.github.ningpp.compat;

import java.util.Arrays;
import java.util.Iterator;
import java.util.NoSuchElementException;

/**
 * Replacement for System.Buffers.ReadOnlySequence&lt;T&gt; (generated by CSharpToJava
 * converter). Array-backed implementation that preserves segment structure:
 * chain-built sequences keep their segments and Slice of a multi-segment
 * sequence stays multi-segment, exactly like .NET.
 */
public final class ReadOnlySequence<T> implements Iterable<ReadOnlyMemory<T>> {

    @SuppressWarnings("rawtypes")
    public static final ReadOnlySequence Empty = new ReadOnlySequence<>();

    private final T[] data;
    private final int start;
    private final int length;
    /** Materialized segment chain (multi-segment sequences only). */
    private final ReadOnlyMemory<T>[] segments;
    /** Running byte index of each segment boundary (multi-segment only). */
    private final long[] runningIndex;
    private final boolean singleSegment;
    private int traversalIndex;

    /** Default (empty) sequence — corresponds to default(ReadOnlySequence&lt;T&gt;). */
    public ReadOnlySequence() {
        this.data = null;
        this.start = 0;
        this.length = 0;
        this.segments = null;
        this.runningIndex = null;
        this.singleSegment = true;
        this.traversalIndex = 0;
    }

    public ReadOnlySequence(T[] data) {
        this(data, 0, data == null ? 0 : data.length);
    }

    /** C# ReadOnlySequence&lt;byte&gt;(byte[]) — boxes each byte as Integer. */
    @SuppressWarnings("unchecked")
    public ReadOnlySequence(byte[] data) {
        this((T[]) boxBytes(data), 0, data == null ? 0 : data.length);
    }

    private static Integer[] boxBytes(byte[] data) {
        if (data == null) {
            return null;
        }
        Integer[] boxed = new Integer[data.length];
        for (int i = 0; i < data.length; i++) {
            boxed[i] = data[i] & 0xFF;
        }
        return boxed;
    }

    public ReadOnlySequence(T[] data, int start, int length) {
        this.data = data;
        this.start = start;
        this.length = length;
        this.segments = null;
        this.runningIndex = null;
        this.singleSegment = true;
        this.traversalIndex = 0;
    }

    /** Wraps a single ReadOnlyMemory as a one-segment sequence. */
    public ReadOnlySequence(ReadOnlyMemory<T> memory) {
        ReadOnlySpan<T> span = memory.getSpan();
        this.data = span.toArray();
        this.start = 0;
        this.length = span.length();
        this.segments = null;
        this.runningIndex = null;
        this.singleSegment = true;
        this.traversalIndex = 0;
    }

    /**
     * Mirrors the segment-chain constructor
     * ReadOnlySequence(ReadOnlySequenceSegment&lt;T&gt;, int, ReadOnlySequenceSegment&lt;T&gt;, int) —
     * materializes the segment chain into the array-backed storage.
     */
    @SuppressWarnings("unchecked")
    public ReadOnlySequence(ReadOnlySequenceSegment<T> startSegment, int startIndex,
                            ReadOnlySequenceSegment<T> endSegment, int endIndex) {
        if (startSegment == null || endSegment == null) {
            this.data = null;
            this.start = 0;
            this.length = 0;
            this.segments = null;
            this.runningIndex = null;
            this.singleSegment = true;
            this.traversalIndex = 0;
            return;
        }
        java.util.List<ReadOnlyMemory<T>> segList = new java.util.ArrayList<>();
        int total = 0;
        int lastSegmentLength = 0;
        for (ReadOnlySequenceSegment<T> seg = startSegment; seg != null; seg = seg.getNext()) {
            int segLen = seg.getMemory().getLength();
            total += segLen;
            lastSegmentLength = segLen;
            segList.add(seg.getMemory());
            if (seg == endSegment) {
                break;
            }
        }
        T[] merged = (T[]) new Object[total];
        int pos = 0;
        for (ReadOnlySequenceSegment<T> seg = startSegment; seg != null; seg = seg.getNext()) {
            ReadOnlySpan<T> span = seg.getMemory().getSpan();
            int segLen = span.length();
            for (int i = 0; i < segLen; i++) {
                merged[pos++] = span.get(i);
            }
            if (seg == endSegment) {
                break;
            }
        }
        this.data = merged;
        this.start = startIndex;
        // .NET length = (endSegment.RunningIndex + endIndex) -
        //               (startSegment.RunningIndex + startIndex).
        // A trailing EMPTY segment with endIndex=0 is a valid end marker: the
        // sequence still covers every byte before it (JsonTestHelper.GetSequence
        // appends a zero-length last buffer when the data divides evenly).
        int computedLength = total - startIndex - (lastSegmentLength - endIndex);
        this.length = Math.max(computedLength, 0);
        @SuppressWarnings("unchecked")
        ReadOnlyMemory<T>[] segs = (ReadOnlyMemory<T>[]) new ReadOnlyMemory<?>[segList.size()];
        this.segments = segList.toArray(segs);
        this.runningIndex = new long[segments.length + 1];
        for (int i = 0; i < segments.length; i++) {
            runningIndex[i + 1] = runningIndex[i] + segments[i].getLength();
        }
        this.singleSegment = startSegment == endSegment;
        this.traversalIndex = 0;
    }

    /**
     * Segment-preserving slice view: splits the range
     * [sliceStart, sliceStart + mergedLength) of a multi-segment sequence into
     * per-segment pieces — the first and last segments are cut at the slice
     * bounds, interior segments are shared as-is, zero-length pieces are
     * dropped (the .NET enumerator never yields empty segments). The running
     * index is rebased so positions in the slice start at zero.
     */
    @SuppressWarnings("unchecked")
    private ReadOnlySequence(T[] mergedData, int mergedStart, int mergedLength,
                             ReadOnlyMemory<T>[] sourceSegments, long[] sourceRunningIndex,
                             int firstIdx, int lastIdx, long sliceStart) {
        this.data = mergedData;
        this.start = mergedStart;
        this.length = mergedLength;
        java.util.List<ReadOnlyMemory<T>> pieces = new java.util.ArrayList<>(lastIdx - firstIdx + 1);
        for (int i = firstIdx; i <= lastIdx; i++) {
            long segStart = sourceRunningIndex[i];
            long segEnd = sourceRunningIndex[i + 1];
            long pieceStart = Math.max(sliceStart, segStart);
            long pieceEnd = Math.min(sliceStart + (long) mergedLength, segEnd);
            if (pieceEnd > pieceStart) {
                pieces.add(sourceSegments[i].slice((int) (pieceStart - segStart), (int) (pieceEnd - pieceStart)));
            }
        }
        ReadOnlyMemory<T>[] pieceArray =
            pieces.toArray((ReadOnlyMemory<T>[]) new ReadOnlyMemory<?>[0]);
        this.segments = pieceArray;
        this.runningIndex = new long[pieceArray.length + 1];
        for (int i = 0; i < pieceArray.length; i++) {
            this.runningIndex[i + 1] = this.runningIndex[i] + pieceArray[i].getLength();
        }
        this.singleSegment = false;
        this.traversalIndex = 0;
    }

    /** Mirrors ReadOnlySequence&lt;T&gt;.Start — the starting position. */
    public SequencePosition getStart() {
        return new SequencePosition(this, 0);
    }

    /**
     * Mirrors ReadOnlySequence&lt;T&gt;.TryGet(ref SequencePosition, out ReadOnlyMemory&lt;T&gt;, bool).
     * Single-segment implementation: the first call returns the whole sequence,
     * subsequent calls report the end. The wildcard parameter accepts both typed
     * and Object holders without an erasure clash.
     */
    public boolean tryGet(ObjectHolder<SequencePosition> nextPosition, ObjectHolder<? super ReadOnlyMemory<T>> memory, boolean advance) {
        if (segments != null) {
            int offset = nextPosition.value != null && nextPosition.value.getObject() == this
                ? nextPosition.value.getInteger()
                : 0;
            int idx = findSegment(offset);
            if (idx >= segments.length) {
                memory.value = new ReadOnlyMemory<>();
                return false;
            }
            // .NET TryGet: return the memory AT the current position, then
            // advance the position to the start of the next segment. Positions
            // are byte offsets so the reader's "index + consumed" arithmetic works.
            memory.value = segments[idx];
            if (advance) {
                nextPosition.value = new SequencePosition(this, (int) runningIndex[idx + 1]);
            }
            return true;
        }
        if (traversalIndex >= 1 || length == 0) {
            memory.value = new ReadOnlyMemory<>();
            return false;
        }
        traversalIndex++;
        memory.value = getFirst();
        return true;
    }

    /** Mirrors ReadOnlySequence&lt;T&gt;.GetPosition(long, SequencePosition). */
    public SequencePosition getPosition(long offset, SequencePosition position) {
        int base = position != null && position.getObject() == this ? position.getInteger() : 0;
        return new SequencePosition(this, base + (int) offset);
    }

    /** Mirrors ReadOnlySequence&lt;T&gt;.First — the memory at the start position.
     *  C# returns the FIRST segment even when it is empty (the reader's constructor
     *  and GetNextSpan skip empty segments themselves); findSegment(0) would
     *  silently skip a leading empty segment and break position bookkeeping. */
    public ReadOnlyMemory<T> getFirst() {
        if (segments != null && segments.length > 0) {
            return segments[0];
        }
        if (length == 0) {
            return new ReadOnlyMemory<>();
        }
        @SuppressWarnings("unchecked")
        T[] copy = (T[]) Arrays.copyOfRange(data, start, start + length);
        return new ReadOnlyMemory<>(copy);
    }

    /** Mirrors ReadOnlySequence&lt;T&gt;.Length. */
    public long getLength() {
        return length;
    }

    /** Mirrors ReadOnlySequence&lt;T&gt;.IsSingleSegment. */
    public boolean getIsSingleSegment() {
        return singleSegment;
    }

    /** Mirrors ReadOnlySequence&lt;T&gt;.IsEmpty. */
    public boolean getIsEmpty() {
        return length == 0;
    }

    /** Mirrors ReadOnlySequence&lt;T&gt;.Slice(long). */
    public ReadOnlySequence<T> slice(long sliceStart) {
        return slice(sliceStart, length - sliceStart);
    }

    /** Mirrors ReadOnlySequence&lt;T&gt;.Slice(long, long). */
    public ReadOnlySequence<T> slice(long sliceStart, long sliceLength) {
        if (sliceStart < 0 || sliceLength < 0 || sliceStart + sliceLength > length) {
            throw new IndexOutOfBoundsException(
                "start=" + sliceStart + ", length=" + sliceLength + ", sequenceLength=" + length);
        }
        if (sliceLength == 0) {
            return new ReadOnlySequence<>();
        }
        if (segments != null) {
            // .NET Slice preserves the segment structure: a slice that starts and
            // ends in different segments stays multi-segment. Utf8JsonReader derives
            // HasValueSequence from IsSingleSegment (e.g.
            // skipOrConsumeCommentMultiSegmentWithRollback) and foreaches the pieces
            // (compareToSequence / unescapeSequenceAndCompare), so collapsing the
            // slice into the merged array breaks multi-segment reads.
            int firstIdx = findSegment((int) sliceStart);
            int lastIdx = findSegment((int) (sliceStart + sliceLength - 1));
            if (firstIdx < lastIdx) {
                return new ReadOnlySequence<>(data, start + (int) sliceStart, (int) sliceLength,
                    segments, runningIndex, firstIdx, lastIdx, sliceStart);
            }
        }
        return new ReadOnlySequence<>(data, start + (int) sliceStart, (int) sliceLength);
    }

    /** Mirrors ReadOnlySequence&lt;T&gt;.Slice(SequencePosition, SequencePosition) — single-segment pass-through. */
    public ReadOnlySequence<T> slice(SequencePosition start, SequencePosition end) {
        long s = start != null && start.getObject() == this ? start.getInteger() : 0;
        long e = end != null && end.getObject() == this ? end.getInteger() : length;
        return slice(s, Math.max(e - s, 0));
    }

    /** Mirrors ReadOnlySequence&lt;T&gt;.Slice(SequencePosition). */
    public ReadOnlySequence<T> slice(SequencePosition start) {
        long s = start != null && start.getObject() == this ? start.getInteger() : 0;
        return slice(s, Math.max(length - s, 0));
    }

    /** Mirrors ReadOnlySequence&lt;T&gt;.Slice(int, SequencePosition). */
    public ReadOnlySequence<T> slice(int start, SequencePosition end) {
        long e = end != null && end.getObject() == this ? end.getInteger() : length;
        return slice(start, Math.max(e - start, 0));
    }

    /**
     * Maps a byte offset to the segment that contains it. Empty segments have no
     * byte range and are skipped; an offset at/past the end maps to segments.length.
     *
     * <p>{@code runningIndex} is non-decreasing, so the containing segment is found by
     * binary search. This lookup must not be a linear scan: consumers such as
     * Utf8JsonReader.getNextSpan call tryGet once per segment advance, so a scan makes
     * a full traversal of an N-segment sequence O(N^2). With the one-byte-per-segment
     * shape produced by JsonTestHelper.GetSequence(data, 1) that turned a ~0.1s read of
     * the 400KB resource into 94s.
     */
    private int findSegment(int offset) {
        if (offset < 0) {
            return 0;
        }
        int low = 0;
        int high = segments.length - 1;
        int candidate = -1;
        while (low <= high) {
            int mid = (low + high) >>> 1;
            if (runningIndex[mid] <= offset) {
                candidate = mid;
                low = mid + 1;
            } else {
                high = mid - 1;
            }
        }
        // candidate is now the last segment starting at or before the offset; it
        // contains the offset only if the offset does not reach the next segment.
        if (candidate < 0 || offset >= runningIndex[candidate + 1]) {
            return segments.length;
        }
        return candidate;
    }

    /**
     * Iterates the segments — mirrors C# foreach over a ReadOnlySequence. The
     * .NET enumerator skips zero-length segments, and the generated reader's
     * compareToSequence / unescapeSequenceAndCompare foreach loops depend on
     * visiting EVERY segment of a multi-segment sequence.
     */
    @Override
    public Iterator<ReadOnlyMemory<T>> iterator() {
        if (segments == null) {
            return new Iterator<>() {
                private boolean consumed = false;

                @Override
                public boolean hasNext() {
                    return !consumed && length > 0;
                }

                @Override
                public ReadOnlyMemory<T> next() {
                    if (!hasNext()) throw new NoSuchElementException();
                    consumed = true;
                    return getFirst();
                }
            };
        }
        return new Iterator<>() {
            private int index = 0;

            @Override
            public boolean hasNext() {
                while (index < segments.length && segments[index].getLength() == 0) {
                    index++;
                }
                return index < segments.length;
            }

            @Override
            public ReadOnlyMemory<T> next() {
                if (!hasNext()) throw new NoSuchElementException();
                return segments[index++];
            }
        };
    }
}
